import React from 'react';
import Navbar from '../components/Navbar';
import './About.css';

const About = () => {
  return (
    <>
      <Navbar />
      <div className="about-modern-container">
        <div className="about-text-card">
          <h1>About Chintamani Traders</h1>
          <p>
            Founded over two decades ago, Chintamani Traders has established itself as a leader in the EPC sector, specializing in electrical, MEP works, and renewable energy plants.
          </p>
          <p>
            We are dedicated to delivering projects with unmatched quality, efficiency, and safety. Our team believes in driving the future of energy through cutting-edge solutions and sustainable practices.
          </p>
          <div className="badges">
            <span>20+ Years of Expertise</span>
            <span>Trusted Across Industries</span>
            <span>Focused on Sustainability</span>
          </div>
          <a href="/contact" className="cta-button">Get in Touch</a>
        </div>
        <div className="about-image-circle">
          <img src="/images/your-about-image.png" alt="Chintamani Traders" />
        </div>
      </div>
    </>
  );
};

export default About;
